::v-deep .el-dialog__body {
    padding: 0px !important;
}

.user-select-input {
    width: 200px;
    height: 32px;
    background: #ffffff;
    border: 1px solid #d9d9d9;
    border-radius: 3px;
    cursor: default;
    user-select: none;
    font-size: 0;
    overflow: hidden;
    text-align: left;
}

.user-select-input-show {
    width: 168px;
    border-right: 1px solid #d9d9d9;
    height: 30px;
    display: inline-block;
    vertical-align: middle;
    white-space: nowrap;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
    -ms-overflow-style: none;
}

.user-select-input-show::-webkit-scrollbar {
    display: none;
}

.user-select-item {
    line-height: 24px;
    font-weight: 400;
    font-size: 14px;
    color: #4a4c66;
    display: inline-block;
    margin: 3px 5px;
    background: rgba(231, 231, 231, 0.5);
    border-radius: 4px;
    padding: 0 8px;
}

.user-select-item-user-name {
    display: inline-block;
    max-width: 70px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    word-break: break-all;
    vertical-align: middle;
}

.user-select-delete-icon {
    color: #969696;
    font-size: 16px;
    display: inline-block;
    vertical-align: middle;
    margin-left: 14px;
    line-height: 24px;
    cursor: pointer;
}

.user-select-item.user-select-item-show-more {
    margin-left: 0;
    margin-right: 0;
}

.user-select-btn {
    width: 30px;
    height: 30px;
    display: inline-block;
    vertical-align: middle;
    text-align: center;
    cursor: pointer;
}

.icon-qingqibing_gerenxinxi {
    font-size: 14px;
    color: #878787;
    line-height: 30px;
}

.search-user-content {
    width: 100%;
    height: 100%;
    display: flex;
}

.select-part {
    width: 80%;
    border: 1px solid #eaeaea;
    display: flex;
    padding: 10px 10px 10px 0;
}

.selected-part {
    width: 20%;
    border: 1px solid #eaeaea;
    border-left: 0;
    padding: 10px 0;
}

.dept {
    width: 35%;
    height: 100%;
}

.user {
    width: 65%;
    height: 100%;
}

::v-deep .el-checkbox__inner {
    margin: 0 !important;
}

::v-deep .el-table th.is-leaf {
    border-bottom: 1px solid #eaeaea;
}

.div-label {
    height: 32px;
    display: flex;
    align-items: center;
    padding: 0 12px;

    &.div-pop {
        cursor: pointer;

        &:hover {
            background: #e9f4fe;
            color: #0d8eff;
        }
    }
}

::v-deep .workFlow-dialog {
    height: 544px;

    .el-table .cell:empty::before {
        content: '';
    }

    .el-table .el-table__row .cell {
        padding: 0 5px;
    }


    .cont-inp-box {
        margin-bottom: 10px;
        padding-left: 16px;
        position: relative;
    }

    .table-tit {
        margin: 9px 7px;

        span {
            color: #bcbdbf;
            font-weight: normal;
        }

        .organ-name {
            display: inline-block;
            overflow: hidden;
            white-space: nowrap;
            text-overflow: ellipsis;
            max-width: calc(100% - 65px);
            color: #4a4c66 !important;
            font-weight: bold !important;
        }
    }

    .table_box {
        height: calc(100% - 106px);
    }

    .page-box {
        margin-right: 16px;
        height: 56px;
        display: flex;
        align-items: center;
        justify-content: flex-end;
    }

    .list-tit {
        display: flex !important;
        justify-content: space-between !important;
        align-items: center !important;

    }

    .node-ul {
        li {
            cursor: default;

            i {
                display: none;
                cursor: pointer;
            }

            &:hover {
                i {
                    display: block;
                }

                color: #4a4c66;

                .item-name {
                    color: inherit;
                }
            }
        }
    }
}


.selected-user-main {
    margin-left: 10px;
}
